const rows = $input.all().map((item) => item.json || {});
const storeSet = new Set();
const mapThresholds = {};
let minPriceChangePercent = 3;
let maxProductsPerStore = 500;

for (const row of rows) {
  const rawUrl = row.storeUrl || row.store_url || row.url || '';
  if (typeof rawUrl === 'string' && rawUrl.trim().length > 0) {
    storeSet.add(rawUrl.trim());
  }
  const key = String(row.sku || row.handle || '').trim();
  const mapVal = Number(row.mapPrice ?? row.map_price);
  if (key && Number.isFinite(mapVal) && mapVal > 0) {
    mapThresholds[key] = mapVal;
  }
  const pct = Number(row.minPriceChangePercent ?? row.min_price_change_percent);
  if (Number.isFinite(pct) && pct >= 0 && pct <= 100) {
    minPriceChangePercent = pct;
  }
  const maxP = Number(row.maxProductsPerStore ?? row.max_products_per_store);
  if (Number.isFinite(maxP) && maxP >= 50 && maxP <= 2500) {
    maxProductsPerStore = Math.round(maxP);
  }
}

const storeUrls = storeSet.size > 0 ? Array.from(storeSet) : ['https://www.allbirds.com'];

return [
  {
    json: {
      storeUrls,
      stateStoreName: 'shopify-delta-monitor-state',
      maxProductsPerStore,
      minPriceChangePercent,
      mapThresholds,
      eventTypes: [
        'price_drop',
        'price_increase',
        'restocked',
        'out_of_stock',
        'new_product',
        'discount_started',
        'discount_ended',
        'map_violation'
      ],
      emitBaselineSummary: true
    }
  }
];

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json || {};
  const pct = typeof d.priceChangePercent === 'number' ? d.priceChangePercent : Number(d.priceChangePercent || 0);
  const isMapViolation = d.mapViolation === true;
  const eventType = String(d.eventType || 'unknown');

  let severity = 'CATALOG';
  if (isMapViolation || (eventType === 'price_drop' && pct <= -15)) {
    severity = 'CRITICAL';
  } else if (eventType === 'restocked' || eventType === 'out_of_stock') {
    severity = 'INVENTORY';
  }

  const variantLabel = d.variantTitle ? ` (${d.variantTitle})` : '';
  const priceLine =
    d.oldPrice != null && d.newPrice != null
      ? `${d.oldPrice} -> ${d.newPrice} (${pct > 0 ? '+' : ''}${pct}%)`
      : d.newPrice != null
        ? `${d.newPrice}`
        : 'N/A';
  const mapLine = isMapViolation
    ? `YES (MAP: ${d.mapPrice ?? 'N/A'})`
    : 'No';

  const emoji =
    severity === 'CRITICAL' ? ':rotating_light:' : severity === 'INVENTORY' ? ':package:' : ':label:';

  const slackSummary = [
    `${emoji} *[${severity}] Shopify Competitor Delta* (\`${eventType}\`)`,
    `*Store:* ${d.store || d.storeKey || 'Unknown'}`,
    `*Product:* ${d.title || 'Untitled'}${variantLabel}`,
    `*SKU:* ${d.sku || d.handle || 'N/A'}`,
    `*Price:* ${priceLine}`,
    `*In Stock:* ${d.available === true ? 'Yes' : d.available === false ? 'No' : 'Unknown'} | *MAP Violation:* ${mapLine}`,
    `*Detected:* ${d.detectedAt || new Date().toISOString()}`,
    `*Link:* ${d.productUrl || ''}`,
  ].join('\n');

  const emailSubject = `[${severity}] ${d.store || 'Shopify Competitor'}: ${d.title || eventType} (${eventType})`;
  const emailBody = [
    `Severity: ${severity}`,
    `Event: ${eventType}`,
    `Store: ${d.store || d.storeKey || 'Unknown'}`,
    `Product: ${d.title || 'Untitled'}${variantLabel}`,
    `SKU: ${d.sku || d.handle || 'N/A'}`,
    `Price Change: ${priceLine}`,
    `MAP Price: ${d.mapPrice ?? 'N/A'} | MAP Violation: ${mapLine}`,
    `In Stock: ${d.available}`,
    `Detected At: ${d.detectedAt || 'N/A'}`,
    `Product URL: ${d.productUrl || 'N/A'}`,
  ].join('\n');

  results.push({
    json: {
      ...d,
      severity,
      slackSummary,
      emailSubject,
      emailBody,
    },
  });
}

return results;
